<?php
declare(strict_types=1);require dirname(__DIR__).'/vendor/autoload.php';use Ogpn\Bot\{Bootstrap,Settings};
$root=Bootstrap::root();$config=$root.'/storage/secrets/server-config.php';if(!is_file($config)){fwrite(STDERR,"Configuration absente : copiez config/server-config.example.php vers storage/secrets/server-config.php puis complétez-la.\n");exit(2);}echo "Vérification de la configuration...\n";$pdo=Bootstrap::pdo();$pdo->query('SELECT 1');echo "Connexion MySQL : OK\n";$pdo->exec((string)file_get_contents($root.'/processing/schema.sql'));
$defaults=Bootstrap::defaults();Settings::set($pdo,'queue.high_threshold',$defaults['queue']['high_threshold']);Settings::set($pdo,'queue.low_threshold',$defaults['queue']['low_threshold']);Settings::set($pdo,'features.discovery_enabled',true);Settings::set($pdo,'features.scan_enabled',true);Settings::set($pdo,'features.emergency_stop',false);Settings::set($pdo,'orchestrator.mode','discovery');
$workers=[['infomaniak-1','infomaniak','discovery','low'],['ovh-1','ovh','discovery','medium'],['github-1','github','scan','high'],['render-1','render','scan','high']];$tokens=[];
foreach($workers as [$id,$platform,$role,$capacity]){$token=bin2hex(random_bytes(32));$perms=['worker.plan'];if($role==='discovery')array_push($perms,'discovery.claim','discovery.ingest','discovery.fail');else array_push($perms,'scan.claim','scan.ingest','scan.fail');$s=$pdo->prepare('INSERT INTO v2_workers(worker_id,platform,preferred_role,capacity,token_hash,permissions) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE platform=VALUES(platform),preferred_role=VALUES(preferred_role),capacity=VALUES(capacity),token_hash=VALUES(token_hash),permissions=VALUES(permissions),enabled=1');$s->execute([$id,$platform,$role,$capacity,hash('sha256',$token),json_encode($perms)]);$tokens[$id]=$token;}
$mcpToken=bin2hex(random_bytes(32));$pdo->prepare('INSERT INTO v2_mcp_clients(client_id,token_hash,permissions,enabled) VALUES(?,?,?,1) ON DUPLICATE KEY UPDATE token_hash=VALUES(token_hash),permissions=VALUES(permissions),enabled=1')->execute(['chatgpt-ogpn',hash('sha256',$mcpToken),json_encode(['mcp.status.read','mcp.domain.read','mcp.statistics.read','mcp.configuration.read','mcp.diagnostics.read'])]);$tokens['mcp:chatgpt-ogpn']=$mcpToken;
$file=$root.'/storage/secrets/generated-tokens.php';file_put_contents($file,"<?php\ndeclare(strict_types=1);\nreturn ".var_export($tokens,true).";\n",LOCK_EX);@chmod($file,0600);@chmod($root.'/storage/secrets',0700);
echo "\nInstallation terminée. Tokens enregistrés dans storage/secrets/generated-tokens.php (mode 600).\n";foreach($tokens as $id=>$token)echo "$id = $token\n";echo "\nLe worker Infomaniak peut désormais être lancé simplement avec : php worker/run.php\n";
